function tone(freq,duration=.7,offset=0){audio ||=new(window.AudioContext||window.webkitAudioContext)();audio.resume();const o=audio.createOscillator(),g=audio.createGain();o.type='triangle';o.frequency.value=freq;g.gain.setValueAtTime(0,audio.currentTime+offset);g.gain.linearRampToValueAtTime(.16,audio.currentTime+offset+.025);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+offset+duration);o.connect(g).connect(audio.destination);o.start(audio.currentTime+offset);o.stop(audio.currentTime+offset+duration);}
